 13→interface CandidateRowProps {
 14→  result: Result;
 15→  index: number;
 16→  isSelected: boolean;
 17→  isActive: boolean;
 18→  jobId?: string | null;
 19→  jobTitle?: string | null;
 20→  onSelect: (id: string) => void;
 21→  onToggleSelect: (resumeId: string) => void;
 22→  onDownload: (filePath: string, filename: string) => void;
 23→  onDismiss: (resumeId: string) => void;
 24→  formatCandidateName: (filename: string) => string;
 25→  currentStage?: HiringStage | null;
 26→  isDuplicate?: boolean;
 27→}
