 95→                  Duplicate
 96→                </Badge>
 97→              )}
 98→              {!r.pending && currentStage && currentStage !== "applied" && (
 99→                <Badge
100→                  variant="outline"
101→                  className={`text-[10px] px-1.5 py-0 h-4 capitalize border font-medium ${STAGE_BADGE_CLASSES[currentStage] ?? ""}`}
102→                >
103→                  {currentStage}
104→                </Badge>
105→              )}
106→            </div>
107→            {r.candidate_location && (
108→              <span className="flex items-center gap-1 text-xs text-muted-foreground">
109→                <MapPin className="h-3 w-3" /> {r.candidate_location}
110→              </span>
111→            )}
112→          </div>
113→        </TableCell>
114→        <TableCell>
115→          {r.pending ? (
116→            <Badge variant="outline" className="text-xs">Pending</Badge>
117→          ) : (
118→            <div className="flex items-center gap-2">
119→              <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[100px]">
120→                <div
121→                  className={`h-full rounded-full transition-all ${getScoreColor(r.overall_score)}`}
122→                  style={{ width: `${Math.min(r.overall_score, 100)}%` }}
123→                />
124→              </div>
125→              <span className={`text-sm font-semibold tabular-nums min-w-[3ch] ${getScoreTextColor(r.overall_score)}`}>
126→                {r.overall_score?.toFixed(0)}%
127→              </span>
128→            </div>
129→          )}
130→        </TableCell>
131→        <TableCell>
132→          <div className="flex flex-wrap items-center gap-1">
133→            {!r.pending && strength && (
134→              <Badge variant={strength.variant} className="text-[10px]">{strength.label}</Badge>
135→            )}
136→            {!r.pending && r.scoring_version === "heuristic" && (
137→              <span className="inline-flex items-center text-[10px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground font-medium">Quick</span>
138→            )}
139→          </div>
140→        </TableCell>
141→        <TableCell>
142→          <div className="flex items-center gap-0.5" onClick={(e) => e.stopPropagation()}>
143→            <TooltipProvider delayDuration={300}>
144→              {r.candidate_phone && (
145→                <Tooltip>
146→                  <TooltipTrigger asChild>
147→                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary"
148→                      onClick={() => { navigator.clipboard.writeText(r.candidate_phone!); toast.success("Phone copied!"); }}>
149→                      <Phone className="h-3.5 w-3.5" />
150→                    </Button>
151→                  </TooltipTrigger>
152→                  <TooltipContent>{r.candidate_phone}</TooltipContent>
153→                </Tooltip>
154→              )}
155→              {r.candidate_email && (
156→                <Tooltip>
157→                  <TooltipTrigger asChild>
158→                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary"
159→                      onClick={() => setEmailDialogOpen(true)}>
160→                      <Mail className="h-3.5 w-3.5" />
161→                    </Button>
162→                  </TooltipTrigger>
163→                  <TooltipContent>Email</TooltipContent>
164→                </Tooltip>
165→              )}
166→              {r.file_path && (
167→                <Tooltip>
168→                  <TooltipTrigger asChild>
169→                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary"
170→                      onClick={() => onDownload(r.file_path!, r.filename)}>
171→                      <FileText className="h-3.5 w-3.5" />
172→                    </Button>
173→                  </TooltipTrigger>
174→                  <TooltipContent>Download</TooltipContent>
175→                </Tooltip>
176→              )}
177→              <Tooltip>
178→                <TooltipTrigger asChild>
179→                  <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-amber-500"
180→                    onClick={() => onDismiss(r.resume_id)}>
181→                    <Archive className="h-3.5 w-3.5" />
182→                  </Button>
183→                </TooltipTrigger>
184→                <TooltipContent>Archive</TooltipContent>
185→              </Tooltip>
186→            </TooltipProvider>
187→          </div>
188→        </TableCell>
189→      </TableRow>
190→
191→      {r.candidate_email && (
192→        <EmailOutreachDialog
193→          open={emailDialogOpen}
194→          onOpenChange={setEmailDialogOpen}
195→          candidateName={r.candidate_name || r.filename}
196→          candidateEmail={r.candidate_email}
197→          jobTitle={jobTitle || "Open Position"}
198→          matchScore={Math.round(r.overall_score ?? 0)}
199→          resumeId={r.resume_id}
200→          jobId={jobId || ""}
201→        />
202→      )}
203→    </>
204→  );
205→};
206→
207→export default CandidateRow;
