 20→/** Get user initials from email or name */
 21→function getInitials(email?: string | null): string {
 22→  if (!email) return "?";
 23→  const name = email.split("@")[0];
 24→  const parts = name.split(/[._-]/);
 25→  if (parts.length >= 2) {
 26→    return (parts[0][0] + parts[1][0]).toUpperCase();
 27→  }
 28→  return name[0]?.toUpperCase() || "?";
 29→}
