 61→          </Link>
 62→
 63→          {/* Right side */}
 64→          <div className="flex items-center gap-2">
 65→            <ThemeToggle />
 66→            {user ? (
 67→              <>
 68→                {/* Credits badge */}
 69→                <button
 70→                  onClick={() => navigate("/settings")}
 71→                  className={`group inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 outline-none focus-visible:ring-2 focus-visible:ring-offset-2 border ${
 72→                    isLowCredits
